import type { Slot } from 'dedal'

// component → props: the only shared thing
export type Contract = {
  grid: { columns?: 1 | 2 | 3 | 4 }
  card: { title?: string; href?: string; badge?: Slot }
  badge: { label?: string }
}

import { Render, type Registry } from 'dedal/react'
import { Card, Badge } from '@/components/ui'

const registry = { grid: Grid, card: Card, badge: Badge }
  satisfies Registry<Contract> // missing one = compile error

export default async function Home() {
  return <Render tree={await home()} registry={registry} />
}

